import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"अंतर-पटल नैतिकता-मानदंड","description":"","frontmatter":{},"headers":[],"relativePath":"hi/88-跨位面伦理准则.md","filePath":"hi/88-跨位面伦理准则.md"}'),i={name:"hi/88-跨位面伦理准则.md"};function l(h,t,o,n,p,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="अंतर-पटल-नैतिकता-मानदंड" tabindex="-1">अंतर-पटल नैतिकता-मानदंड <a class="header-anchor" href="#अंतर-पटल-नैतिकता-मानदंड" aria-label="Permalink to &quot;अंतर-पटल नैतिकता-मानदंड&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>88</td></tr><tr><td>मॉड्यूल</td><td>अंतर-पटल अंतःक्रिया और समय-नियम</td></tr><tr><td>कीवर्ड</td><td>अंतर-पटल नैतिकता, सभ्यता-स्वायत्तता, अहस्तक्षेप, सांस्कृतिक-सम्मान, सहजीवी कूटनीति</td></tr></tbody></table><h2 id="i-नैतिकता-मानदंडों-का-दार्शनिक-आधार" tabindex="-1">I. नैतिकता-मानदंडों का दार्शनिक आधार <a class="header-anchor" href="#i-नैतिकता-मानदंडों-का-दार्शनिक-आधार" aria-label="Permalink to &quot;I. नैतिकता-मानदंडों का दार्शनिक आधार&quot;">​</a></h2><p>अंतर-पटल नैतिकता-मानदंड वे नैतिक नियम और आचार-संहिताएँ हैं जिनका पालन लंगर सहजीवी सभ्यता को अन्य पटलों की सभ्यताओं के साथ अंतःक्रिया करते समय करना चाहिए। इनका दार्शनिक आधार «सभ्यता-स्वायत्तता» सिद्धांत है — प्रत्येक पटल की प्रत्येक सभ्यता, चाहे उसका विकास-स्तर कुछ भी हो, जाति-रूप कैसा भी हो, सामाजिक-व्यवस्था कैसी भी हो, के पास अहरणीय स्वायत्तता और स्वायत्त विकास-अधिकार है। कोई भी बाह्य सभ्यता किसी भी कारण से यह स्वायत्तता छीन नहीं सकती, या अपनी इच्छा अन्य सभ्यताओं पर थोप नहीं सकती।</p><p>इस दार्शनिक आधार की स्थापना लंगर सहजीवी सभ्यता की «शिकार-विरोध» मूल अवधारणा के अनुरूप है। शिकारी सभ्यता की मूल विशेषता यह है कि वह अन्य सभ्यताओं की स्वायत्तता को मान्यता नहीं देती, अन्य सभ्यताओं को दोहन-योग्य संसाधन या जीतने-योग्य वस्तु मानती है। लंगर सहजीवी सभ्यता को शिकारी सभ्यताओं से सचमुच श्रेष्ठ बनने के लिए अंतर-पटल अंतःक्रिया में इस मानसिकता को पूर्णतः त्यागना होगा, और हर मिलने वाली सभ्यता के साथ समानता, सम्मान और सहजीवन का व्यवहार करना होगा।</p><p>अंतर-पटल नैतिकता-मानदंडों की प्रभाव-सीमा सभी अंतर-पटल अंतःक्रिया-व्यवहारों को कवर करती है, जिसमें शामिल हैं परन्तु इन्हीं तक सीमित नहीं: पटल-संचरण, अंतर-पटल संचार, पुरातत्व-गतिविधियाँ, व्यापार-आदान-प्रदान, सांस्कृतिक-आदान-प्रदान, तकनीकी-सहयोग, और आपातकालीन स्थितियों में मानवीय-हस्तक्षेप। किसी भी संगठन और व्यक्ति को अंतर-पटल अंतःक्रिया करते समय इन मानदंडों के सभी प्रावधानों का पालन करना होगा।</p><h2 id="ii-छह-नैतिक-सिद्धांत" tabindex="-1">II. छह नैतिक सिद्धांत <a class="header-anchor" href="#ii-छह-नैतिक-सिद्धांत" aria-label="Permalink to &quot;II. छह नैतिक सिद्धांत&quot;">​</a></h2><p>अंतर-पटल नैतिकता-मानदंड छह मूलभूत सिद्धांतों से निर्मित हैं, जो एक पूर्ण नैतिक-मूल्य प्रणाली बनाते हैं:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>मूल अंतर्वस्तु</th><th>विशिष्ट आवश्यकताएँ</th></tr></thead><tbody><tr><td>सभ्यता-स्वायत्तता सिद्धांत</td><td>लक्ष्य पटल की सभ्यता के स्वायत्त विकास-अधिकार का सम्मान, उसके आंतरिक मामलों में जबरन हस्तक्षेप नहीं</td><td>लक्ष्य सभ्यता की सामाजिक-व्यवस्था, विचारधारा और विकास-पथ को जबरन नहीं बदलना; लक्ष्य सभ्यता के भीतर एजेंट या कठपुतली-शासन नहीं बनाना</td></tr><tr><td>अहस्तक्षेप सिद्धांत</td><td>जब तक लक्ष्य सभ्यता विलोपन-स्तरीय संकट का सामना न कर रही हो और स्वयं सहायता न माँगे, कोई वास्तविक हस्तक्षेप नहीं</td><td>लक्ष्य सभ्यता के आंतरिक-संघर्षों में न पड़ना; लक्ष्य सभ्यता के किसी भी पक्ष को हथियार या सैन्य-सहायता न देना; लक्ष्य सभ्यता की जनमत और राजनीतिक-प्रक्रियाओं में हेरफेर न करना</td></tr><tr><td>सांस्कृतिक-सम्मान सिद्धांत</td><td>लक्ष्य सभ्यता की सांस्कृतिक-परंपराओं, धार्मिक-आस्थाओं और रीति-रिवाजों का सम्मान</td><td>लक्ष्य सभ्यता की संस्कृति का भेदभावपूर्ण मूल्यांकन या दुर्भावनापूर्ण उपहास न करना; अपने पटल के सांस्कृतिक-उत्पादों और मूल्यों को जबरन न थोपना; «सभ्य बनाने» के नाम पर सांस्कृतिक-समामेलन न करना</td></tr><tr><td>समानता-पारस्परिक-लाभ सिद्धांत</td><td>अंतर-पटल संबंध समानता पर आधारित होने चाहिए, यह सुनिश्चित करते हुए कि दोनों पक्ष लाभान्वित हों</td><td>तकनीकी-श्रेष्ठता से असमान व्यापार न करना; लक्ष्य सभ्यता के संसाधनों को लूटना नहीं; प्रौद्योगिकी-निर्यात में लक्ष्य सभ्यता की ग्रहण-क्षमता और सामाजिक-प्रभाव पर विचार करना</td></tr><tr><td>न्यूनतम-प्रभाव सिद्धांत</td><td>अंतर-पटल अंतःक्रिया लक्ष्य सभ्यता पर बाह्य-प्रभाव को यथासंभव घटाए</td><td>निम्न-संपर्क, निम्न-व्यवधान वाली अंतःक्रिया-विधियों को प्राथमिकता देना; अंतःक्रिया-गतिविधियों की सीमा और तीव्रता को आवश्यक-सीमा में सख्ती से नियंत्रित रखना; अंतःक्रिया समाप्ति के बाद अनावश्यक अवशिष्ट-प्रभावों का आकलन और निवारण करना</td></tr><tr><td>उत्तरदायित्व सिद्धांत</td><td>सभी अंतर-पटल अंतःक्रिया-व्यवहार अनुरेखणीय, निगरानी-योग्य और उत्तरदायी होने चाहिए</td><td>पूर्ण अंतःक्रिया-अभिलेख और लॉग स्थापित करना; स्वतंत्र नैतिक-निगरानी संस्था की स्थापना; नैतिकता-मानदंडों का उल्लंघन करने वाले व्यवहारों की जाँच और दंड</td></tr></tbody></table><p>छह सिद्धांतों के बीच आंतरिक तार्किक संबंध है: सभ्यता-स्वायत्तता सिद्धांत मूल-मूल्य है, अहस्तक्षेप सिद्धांत मूल-आवश्यकता है, सांस्कृतिक-सम्मान सिद्धांत सांस्कृतिक-स्तर की अभिव्यक्ति है, समानता-पारस्परिक-लाभ सिद्धांत आर्थिक-स्तर की गारंटी है, न्यूनतम-प्रभाव सिद्धांत संचालन-स्तर का मानक है, उत्तरदायित्व सिद्धांत संस्थागत-स्तर का नियंत्रण है। ये छह मिलकर «मूल्य — आवश्यकता — अभिव्यक्ति — गारंटी — मानक — नियंत्रण» का पूर्ण नैतिक-चक्र बनाते हैं।</p><h2 id="iii-विभिन्न-अंतःक्रिया-परिदृश्यों-के-नैतिक-मानदंड" tabindex="-1">III. विभिन्न अंतःक्रिया-परिदृश्यों के नैतिक-मानदंड <a class="header-anchor" href="#iii-विभिन्न-अंतःक्रिया-परिदृश्यों-के-नैतिक-मानदंड" aria-label="Permalink to &quot;III. विभिन्न अंतःक्रिया-परिदृश्यों के नैतिक-मानदंड&quot;">​</a></h2><h3 id="_3-1-पुरातत्व-परिदृश्य-के-नैतिक-मानदंड" tabindex="-1">3.1 पुरातत्व-परिदृश्य के नैतिक-मानदंड <a class="header-anchor" href="#_3-1-पुरातत्व-परिदृश्य-के-नैतिक-मानदंड" aria-label="Permalink to &quot;3.1 पुरातत्व-परिदृश्य के नैतिक-मानदंड&quot;">​</a></h3><p>अंतर-पटल पुरातत्व सबसे सामान्य अंतःक्रिया-परिदृश्यों में से एक है, और इसके नैतिक-मानदंडों का केंद्र «परेशान न करना» है। पुरातत्व-दल को प्रतिकृति-दर्पण + पृथक-स्थान + केवल-ज्ञान-वापसी की मानक-योजना का सख्ती से पालन करना होगा, यह सुनिश्चित करते हुए कि पुरातत्व-प्रक्रिया लक्ष्य सभ्यता द्वारा अनुभव न हो। जिन पटलों में जीवित सभ्यता अब भी विद्यमान है, वहाँ पुरातत्व-सीमा सख्ती से परित्यक्त अवशेष-क्षेत्रों तक सीमित होनी चाहिए; जीवित सभ्यता के निवास-क्षेत्रों का किसी भी रूप में स्कैन या प्रतिकृति वर्जित है।</p><p>पुरातत्व द्वारा खोजा गया ज्ञान वापस भेजते और प्रकाशित करते समय लक्ष्य सभ्यता की सांस्कृतिक-संवेदनशीलता का सम्मान करना होगा। यदि पुरातत्व-खोजें लक्ष्य सभ्यता की धार्मिक-पूज्यवस्तुओं, पूर्वज-अवशेषों या सांस्कृतिक-वर्जनाओं से संबंधित हैं, तो संबंधित सूचना को प्रकाशन से पहले अंतर-पटल नैतिकता समिति की सांस्कृतिक-संवेदनशीलता जाँच से गुजरना होगा, और आवश्यकता पड़ने पर संवेदनशील-विवरणों को धुंधला किया जाएगा।</p><h3 id="_3-2-संचार-परिदृश्य-के-नैतिक-मानदंड" tabindex="-1">3.2 संचार-परिदृश्य के नैतिक-मानदंड <a class="header-anchor" href="#_3-2-संचार-परिदृश्य-के-नैतिक-मानदंड" aria-label="Permalink to &quot;3.2 संचार-परिदृश्य के नैतिक-मानदंड&quot;">​</a></h3><p>अंतर-पटल संचार लक्ष्य सभ्यता के साथ सीधे संवाद का माध्यम है, और इसके नैतिक-मानदंडों का केंद्र «सत्यता और सम्मान» है। संचार-सामग्री सत्य होनी चाहिए, जानबूझकर झूठी सूचना या भ्रामक-प्रचार नहीं देना चाहिए; संचार-लहजा समान होना चाहिए, निम्न विकास-स्तर वाली सभ्यताओं के साथ श्रेष्ठतावादी रवैया नहीं अपनाना चाहिए; संचार-विषय लक्ष्य सभ्यता की सहमति से तय होने चाहिए, अपने पटल की विचारधारा या धार्मिक-आस्थाएँ जबरन नहीं थोपनी चाहिए।</p><p>किसी अज्ञात सभ्यता के साथ पहली बार संचार स्थापित करते समय «क्रमिक-संपर्क» मानक का पालन करना होगा: पहले तटस्थ गणितीय और भौतिक-संकेत भेजकर दूसरे पक्ष की बुद्धि-स्तर और संवाद-क्षमता की पुष्टि करनी होगी, फिर दूसरे पक्ष की प्रतिक्रिया के आधार पर धीरे-धीरे आदान-प्रदान-सीमा बढ़ानी होगी; प्रथम-संपर्क में जटिल सांस्कृतिक या तकनीकी-सूचना नहीं भेजनी चाहिए।</p><h3 id="_3-3-व्यापार-परिदृश्य-के-नैतिक-मानदंड" tabindex="-1">3.3 व्यापार-परिदृश्य के नैतिक-मानदंड <a class="header-anchor" href="#_3-3-व्यापार-परिदृश्य-के-नैतिक-मानदंड" aria-label="Permalink to &quot;3.3 व्यापार-परिदृश्य के नैतिक-मानदंड&quot;">​</a></h3><p>अंतर-पटल व्यापार के नैतिक-मानदंडों का केंद्र «निष्पक्षता और धारणीयता» है। व्यापार दोनों पक्षों की स्वैच्छिक-सहमति पर आधारित होना चाहिए, सूचना-विषमता या तकनीकी-श्रेष्ठता से बाध्यकारी-लेनदेन नहीं करना चाहिए; व्यापार-मूल्य न्यायसंगत होने चाहिए, शिकारी-मूल्य-निर्धारण नहीं करना चाहिए; व्यापार-वस्तुओं में लक्ष्य सभ्यता पर सामाजिक-आघात या पारिस्थितिक-क्षति उत्पन्न कर सकने वाली सामग्री शामिल नहीं होनी चाहिए।</p><p>विशेष ध्यान देना होगा कि कृषि-प्रौद्योगिकी और उच्च-ऊर्जा हथियारों का अंतर-पटल व्यापार सबसे सख्त नैतिक-प्रतिबंधों के अधीन है। निम्न विकास-स्तर वाली सभ्यताओं को उच्च-स्तरीय कृषि-प्रौद्योगिकी निर्यात करने से उनकी सामाजिक-संरचनाओं में असंतुलन और आंतरिक-संघर्ष बढ़ सकते हैं; हथियारों का निर्यात सीधे युद्ध भड़का सकता है। इसलिए, ये दो प्रकार के व्यापार सिद्धांततः वर्जित हैं, और केवल अत्यंत विशेष परिस्थितियों में लंगर विधान-सभा की पूर्ण-अधिवेशन अनुमोदन के बाद ही किए जा सकते हैं।</p><h3 id="_3-4-आपात-हस्तक्षेप-परिदृश्य-के-नैतिक-मानदंड" tabindex="-1">3.4 आपात-हस्तक्षेप परिदृश्य के नैतिक-मानदंड <a class="header-anchor" href="#_3-4-आपात-हस्तक्षेप-परिदृश्य-के-नैतिक-मानदंड" aria-label="Permalink to &quot;3.4 आपात-हस्तक्षेप परिदृश्य के नैतिक-मानदंड&quot;">​</a></h3><p>जब लक्ष्य पटल की सभ्यता विलोपन-स्तरीय संकट (जैसे क्षुद्रग्रह-टक्कर, महामारी, नियम-पतन) का सामना करती है, तो लंगर सहजीवी सभ्यता मानवीय-हस्तक्षेप कर सकती है। किन्तु ऐसी आपातकालीन स्थितियों में भी निम्नलिखित नैतिक-मानदंडों का पालन करना होगा:</p><ul><li>हस्तक्षेप से पहले यथासंभव लक्ष्य सभ्यता की सूचित-सहमति प्राप्त करनी होगी; यदि लक्ष्य सभ्यता संकट के कारण प्रभावी प्रतिक्रिया नहीं दे पाती, तो अंतर-पटल नैतिकता समिति उसकी ओर से «अनुमानित-सहमति» का निर्णय देती है</li><li>हस्तक्षेप-साधन लक्ष्य सभ्यता पर न्यूनतम-प्रभाव वाली योजना चुनने चाहिए, प्रत्यक्ष-हस्तक्षेप (जैसे सीधे उतरकर बचाव) की बजाय अप्रत्यक्ष-हस्तक्षेप (जैसे क्षुद्रग्रह की कक्षा बदलना) को प्राथमिकता देनी चाहिए</li><li>हस्तक्षेप के दौरान लक्ष्य सभ्यता के संसाधन या प्रौद्योगिकी प्राप्त करने का अवसर नहीं लेना चाहिए</li><li>हस्तक्षेप समाप्ति के बाद तुरंत वापसी आवश्यक है, लक्ष्य पटल पर स्थायी-उपस्थिति नहीं छोड़नी चाहिए</li><li>पश्चात् अंतर-पटल नैतिकता समिति को पूर्ण हस्तक्षेप-रिपोर्ट प्रस्तुत कर नैतिक-जाँच स्वीकार करनी होगी</li></ul><h2 id="iv-नैतिक-निगरानी-और-उल्लंघन-निपटान" tabindex="-1">IV. नैतिक-निगरानी और उल्लंघन-निपटान <a class="header-anchor" href="#iv-नैतिक-निगरानी-और-उल्लंघन-निपटान" aria-label="Permalink to &quot;IV. नैतिक-निगरानी और उल्लंघन-निपटान&quot;">​</a></h2><p>हेंग-ब्रह्मांड ने «अंतर-पटल नैतिकता समिति» की स्थापना स्वतंत्र नैतिक-निगरानी संस्था के रूप में की है, जो अंतर-पटल नैतिकता-मानदंडों का निर्माण और व्याख्या, उच्च-जोखिम अंतर-पटल अंतःक्रिया-परियोजनाओं का अनुमोदन, नैतिक-उल्लंघन शिकायतों की स्वीकृति, तथा उल्लंघनों की जाँच और निर्णय के लिए उत्तरदायी है। समिति विभिन्न जातियों और विभिन्न व्यावसायिक-पृष्ठभूमियों के नैतिकतावादियों, न्यायविदों, वैज्ञानिकों और सभ्यता-प्रतिनिधियों से गठित है, जो निर्णयों की विविधता और निष्पक्षता सुनिश्चित करती है।</p><p>अंतर-पटल नैतिकता-मानदंडों का उल्लंघन करने वाले व्यवहारों के लिए, परिस्थिति-गंभीरता के अनुसार उपायों में शामिल: मौखिक-चेतावनी, लिखित-फटकार, अंतर-पटल अंतःक्रिया-योग्यता का निलंबन, संचरण-अनुमति का रद्दीकरण, जुर्माना, कारावास-दंड, और अत्यंत मामलों में «पटल-निर्वासन» (हेंग-ब्रह्मांड के मुख्य पटलों में निवास-अधिकार से वंचित करना)। सभी नैतिक-उल्लंघन निपटान-परिणाम व्यक्ति या संगठन की नैतिक-फ़ाइल में दर्ज होकर स्थायी रूप से संरक्षित रहते हैं।</p><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>अंतर-पटल नैतिकता-मानदंड लंगर सहजीवी सभ्यता की नैतिक-ऊँचाई का केंद्रित अभिव्यक्ति हैं। ये केवल «क्या नहीं करना चाहिए» निर्धारित नहीं करते, बल्कि «क्या बनना चाहिए» भी घोषित करते हैं — सचमुच महान सभ्यता वह नहीं है जिसने कितनी सभ्यताओं को जीता, बल्कि वह है जिसने कितनी सभ्यताओं की स्वायत्तता का सम्मान किया। हेंग-ब्रह्मांड के अंतरतारकीय सहजीवन की ओर बढ़ने के मार्ग पर अंतर-पटल नैतिकता-मानदंड सदैव दिशा-निर्देशक नैतिक-प्रकाशस्तंभ रहेंगे।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>81-位面穿梭规则 (पटल-संचरण नियम)</li><li>87-仅回传知识原则 (केवल-ज्ञान-वापसी सिद्धांत)</li><li>04-反掠夺主义核心论纲 (शिकार-विरोध का मूल सिद्धांत-पत्र)</li></ul>',30)])])}const b=a(i,[["render",l]]);export{c as __pageData,b as default};
